// SageMaker Pipeline definition (schema 2020-12-01) written as plain JSON,
// so every step is visible as code instead of being generated by the SDK.
//
//   PrepareData ─┬─> Baseline ───────────────────────────────┐
//   (Athena →    └─> Train ──> Evaluate ──> CheckAuc ──┬─> RegisterModel
//    validate/split)                                   └─> FailLowAuc
//
// Reference (step types and their arguments):
//   https://docs.aws.amazon.com/sagemaker/latest/dg/build-and-manage-steps.html
const { imageVersion } = require('../../container/image-version')

const PROCESSING = '/opt/ml/processing'

// Std:Join → s3://<bucket>/<prefix>/<execution id>/<...parts>
const executionUri = (base, ...parts) => ({
  'Std:Join': {
    On: '/',
    Values: [base, { Get: 'Execution.PipelineExecutionId' }, ...parts],
  },
})

const s3Input = (name, uri, localPath) => ({
  InputName: name,
  AppManaged: false,
  S3Input: {
    S3Uri: uri,
    LocalPath: localPath,
    S3DataType: 'S3Prefix',
    S3InputMode: 'File',
    S3DataDistributionType: 'FullyReplicated',
    S3CompressionType: 'None',
  },
})

const s3Output = (name, uri, localPath) => ({
  OutputName: name,
  AppManaged: false,
  S3Output: { S3Uri: uri, LocalPath: localPath, S3UploadMode: 'EndOfJob' },
})

const outputUri = (step, name) => ({
  Get: `Steps.${step}.ProcessingOutputConfig.Outputs['${name}'].S3Output.S3Uri`,
})

const cluster = (instanceType) => ({
  ClusterConfig: {
    InstanceType: instanceType,
    InstanceCount: 1,
    VolumeSizeInGB: 30,
  },
})

module.exports = async ({ resolveVariable }) => {
  const custom = (key) => resolveVariable(`self:custom.${key}`)
  const [
    accountId,
    roleName,
    artifactsBucket,
    projectPrefix,
    repositoryUri,
    database,
    curatedTable,
    athenaWorkGroup,
    modelPackageGroupName,
    minRocAuc,
    realtimeInstanceTypes,
    transformInstanceTypes,
  ] = await Promise.all([
    resolveVariable('aws:accountId'),
    custom('iam.sageMakerRoleName'),
    custom('s3.artifactsBucketName'),
    custom('prefixes.pipeline'),
    custom('image.repositoryUri'),
    custom('glue.databaseName'),
    custom('glue.curatedTableName'),
    custom('athena.pipelineWorkGroupName'),
    custom('registry.modelPackageGroupName'),
    custom('pipeline.minRocAuc'),
    custom('registry.realtimeInstanceTypes'),
    custom('registry.transformInstanceTypes'),
  ])

  const roleArn = `arn:aws:iam::${accountId}:role/${roleName}`
  // One immutable image (content-hash tag) for every step of the project.
  const imageTag = imageVersion()
  const modelImage = `${repositoryUri}:${imageTag}`
  const runBase = `s3://${artifactsBucket}/${projectPrefix}/executions`
  const evaluationUri = executionUri(runBase, 'evaluation', 'evaluation.json')
  const statisticsUri = executionUri(runBase, 'baseline', 'statistics.json')
  const constraintsUri = executionUri(runBase, 'baseline', 'constraints.json')
  const modelArtifacts = { Get: 'Steps.Train.ModelArtifacts.S3ModelArtifacts' }
  const script = (module) => [
    'python3',
    '-m',
    `src.pipelines.training.${module}`,
  ]

  const curatedQuery =
    `SELECT * FROM "${database}"."${curatedTable}" ` +
    `WHERE ingestion_date = (SELECT max(ingestion_date) ` +
    `FROM "${database}"."${curatedTable}")`

  // 1. Data preparation: SageMaker runs the Athena query itself (dataset
  //    definition), then preprocess.py validates and splits the data.
  const prepareData = {
    Name: 'PrepareData',
    Type: 'Processing',
    Description: 'Athena (curated table) → validation → train/val/test split',
    Arguments: {
      ProcessingResources: cluster({
        Get: 'Parameters.ProcessingInstanceType',
      }),
      AppSpecification: {
        ImageUri: modelImage,
        ContainerEntrypoint: script('preprocess'),
        ContainerArguments: ['--min-rows', { Get: 'Parameters.MinRows' }],
      },
      RoleArn: roleArn,
      ProcessingInputs: [
        {
          InputName: 'curated',
          AppManaged: false,
          DatasetDefinition: {
            AthenaDatasetDefinition: {
              Catalog: 'AwsDataCatalog',
              Database: database,
              QueryString: curatedQuery,
              WorkGroup: athenaWorkGroup,
              OutputS3Uri: `s3://${artifactsBucket}/${projectPrefix}/athena/`,
              OutputFormat: 'JSON',
            },
            LocalPath: `${PROCESSING}/input/data`,
            DataDistributionType: 'FullyReplicated',
            InputMode: 'File',
          },
        },
      ],
      ProcessingOutputConfig: {
        Outputs: ['train', 'validation', 'test', 'baseline'].map((name) =>
          s3Output(
            name,
            executionUri(runBase, 'data', name),
            `${PROCESSING}/${name}`
          )
        ),
      },
      StoppingCondition: { MaxRuntimeInSeconds: 1800 },
    },
  }

  // 2. Drift baseline: reference profile of the training data (bins and
  //    frequencies per feature) + thresholds. Registered as the model's drift
  //    check baseline; the DataDrift Lambda compares live traffic against it.
  const baseline = {
    Name: 'Baseline',
    Type: 'Processing',
    Description: 'Data drift reference profile of the training data',
    Arguments: {
      ProcessingResources: cluster({
        Get: 'Parameters.ProcessingInstanceType',
      }),
      AppSpecification: {
        ImageUri: modelImage,
        ContainerEntrypoint: script('baseline'),
      },
      RoleArn: roleArn,
      ProcessingInputs: [
        s3Input(
          'baseline_dataset_input',
          outputUri('PrepareData', 'baseline'),
          `${PROCESSING}/input/baseline_dataset_input`
        ),
      ],
      ProcessingOutputConfig: {
        Outputs: [
          s3Output(
            'monitoring_output',
            executionUri(runBase, 'baseline'),
            `${PROCESSING}/output`
          ),
        ],
      },
      StoppingCondition: { MaxRuntimeInSeconds: 1800 },
    },
  }

  // 3. Training: SageMaker runs `<image> train`. Printed metrics are
  //    captured by MetricDefinitions (Experiments / CloudWatch).
  const train = {
    Name: 'Train',
    Type: 'Training',
    Description: 'scikit-learn Pipeline (preprocessing + gradient boosting)',
    Arguments: {
      AlgorithmSpecification: {
        TrainingImage: modelImage,
        TrainingInputMode: 'File',
        MetricDefinitions: ['auc', 'average_precision', 'f1', 'recall'].map(
          (metric) => ({
            Name: `validation:${metric}`,
            Regex: `validation:${metric}=([0-9\\.]+)`,
          })
        ),
      },
      HyperParameters: {
        max_iter: { Get: 'Parameters.MaxIter' },
        learning_rate: { Get: 'Parameters.LearningRate' },
        max_depth: { Get: 'Parameters.MaxDepth' },
      },
      RoleArn: roleArn,
      InputDataConfig: ['train', 'validation'].map((name) => ({
        ChannelName: name,
        ContentType: 'text/csv',
        DataSource: {
          S3DataSource: {
            S3DataType: 'S3Prefix',
            S3Uri: outputUri('PrepareData', name),
            S3DataDistributionType: 'FullyReplicated',
          },
        },
      })),
      OutputDataConfig: { S3OutputPath: executionUri(runBase, 'model') },
      ResourceConfig: {
        InstanceCount: 1,
        InstanceType: { Get: 'Parameters.TrainingInstanceType' },
        VolumeSizeInGB: 30,
      },
      StoppingCondition: { MaxRuntimeInSeconds: 3600 },
    },
  }

  // 4. Offline evaluation on the held-out test split → evaluation.json,
  //    exposed to the pipeline as a PropertyFile.
  const evaluate = {
    Name: 'Evaluate',
    Type: 'Processing',
    Description: 'Test split metrics (Model Registry format)',
    Arguments: {
      ProcessingResources: cluster({
        Get: 'Parameters.ProcessingInstanceType',
      }),
      AppSpecification: {
        ImageUri: modelImage,
        ContainerEntrypoint: script('evaluate'),
      },
      RoleArn: roleArn,
      ProcessingInputs: [
        s3Input('model', modelArtifacts, `${PROCESSING}/model`),
        s3Input('test', outputUri('PrepareData', 'test'), `${PROCESSING}/test`),
      ],
      ProcessingOutputConfig: {
        Outputs: [
          s3Output(
            'evaluation',
            executionUri(runBase, 'evaluation'),
            `${PROCESSING}/evaluation`
          ),
        ],
      },
      StoppingCondition: { MaxRuntimeInSeconds: 1800 },
    },
    PropertyFiles: [
      {
        PropertyFileName: 'EvaluationReport',
        OutputName: 'evaluation',
        FilePath: 'evaluation.json',
      },
    ],
  }

  // 6a. Register a new model package version (Model Registry). It waits in
  //     PendingManualApproval until a human approves it.
  const registerModel = {
    Name: 'RegisterModel',
    Type: 'RegisterModel',
    Description: 'New model package version (pending manual approval)',
    DependsOn: ['Baseline'],
    Arguments: {
      ModelPackageGroupName: modelPackageGroupName,
      ModelPackageDescription: `image ${modelImage}`,
      ModelApprovalStatus: { Get: 'Parameters.ModelApprovalStatus' },
      InferenceSpecification: {
        Containers: [
          {
            // Endpoints and Batch Transform run `<image> serve`.
            Image: modelImage,
            ModelDataUrl: modelArtifacts,
          },
        ],
        SupportedContentTypes: ['text/csv', 'application/json'],
        SupportedResponseMIMETypes: ['application/json', 'text/csv'],
        SupportedRealtimeInferenceInstanceTypes: realtimeInstanceTypes,
        SupportedTransformInstanceTypes: transformInstanceTypes,
      },
      ModelMetrics: {
        ModelQuality: {
          Statistics: { ContentType: 'application/json', S3Uri: evaluationUri },
        },
        ModelDataQuality: {
          Statistics: { ContentType: 'application/json', S3Uri: statisticsUri },
          Constraints: {
            ContentType: 'application/json',
            S3Uri: constraintsUri,
          },
        },
      },
      DriftCheckBaselines: {
        ModelDataQuality: {
          Statistics: { ContentType: 'application/json', S3Uri: statisticsUri },
          Constraints: {
            ContentType: 'application/json',
            S3Uri: constraintsUri,
          },
        },
      },
      CustomerMetadataProperties: {
        ImageTag: imageTag,
        TriggeredBy: { Get: 'Parameters.TriggeredBy' },
      },
    },
  }

  // 6b. Quality gate failed: stop with an explicit error (no registration).
  const failLowAuc = {
    Name: 'FailLowAuc',
    Type: 'Fail',
    Arguments: {
      ErrorMessage: {
        'Std:Join': {
          On: ' ',
          Values: [
            'Test ROC AUC below the minimum',
            { Get: 'Parameters.MinRocAuc' },
          ],
        },
      },
    },
  }

  // 5. Quality gate: only models good enough on the test split get
  //    registered.
  const checkAuc = {
    Name: 'CheckAuc',
    Type: 'Condition',
    Arguments: {
      Conditions: [
        {
          Type: 'GreaterThanOrEqualTo',
          LeftValue: {
            'Std:JsonGet': {
              PropertyFile: {
                Get: 'Steps.Evaluate.PropertyFiles.EvaluationReport',
              },
              Path: 'binary_classification_metrics.auc.value',
            },
          },
          RightValue: { Get: 'Parameters.MinRocAuc' },
        },
      ],
      IfSteps: [registerModel],
      ElseSteps: [failLowAuc],
    },
  }

  const definition = {
    Version: '2020-12-01',
    Metadata: {},
    Parameters: [
      {
        Name: 'ProcessingInstanceType',
        Type: 'String',
        DefaultValue: 'ml.m5.large',
      },
      {
        Name: 'TrainingInstanceType',
        Type: 'String',
        DefaultValue: 'ml.m5.large',
      },
      { Name: 'MinRows', Type: 'String', DefaultValue: '500' },
      { Name: 'MaxIter', Type: 'String', DefaultValue: '300' },
      { Name: 'LearningRate', Type: 'String', DefaultValue: '0.05' },
      { Name: 'MaxDepth', Type: 'String', DefaultValue: '4' },
      { Name: 'MinRocAuc', Type: 'Float', DefaultValue: Number(minRocAuc) },
      {
        Name: 'ModelApprovalStatus',
        Type: 'String',
        DefaultValue: 'PendingManualApproval',
      },
      { Name: 'TriggeredBy', Type: 'String', DefaultValue: 'manual' },
    ],
    PipelineExperimentConfig: {
      ExperimentName: { Get: 'Execution.PipelineName' },
      TrialName: { Get: 'Execution.PipelineExecutionId' },
    },
    Steps: [prepareData, baseline, train, evaluate, checkAuc],
  }

  return JSON.stringify(definition)
}
